window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bd392762dbe667e8"]={"versions": [{"id": "FIG-bd392762dbe667e8", "releases": ["R22-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitliches Ablauf- und Semantikdiagramm (Timing/Execution Model) nach dem Paradigma der <em>Logical Execution Time</em> (LET).</li>\n<li><strong>Technischer Zweck:</strong> Definition der zeitinvarianten, deterministischen Ausführungssemantik für Software-Komponenten (SWC) im AUTOSAR-Gesamtsystem (Classic & Adaptive Platform, spezifiziert im AUTOSAR Glossary sowie in <code>AUTOSAR_TPS_TimingExtensions</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Entkopplung des logischen Zeitverhaltens von der physischen Rechenzeit (Execution Time / Scheduling Jitter). Das Modell garantiert deterministisches Kommunikations- und Echtzeitverhalten unabhängig von Core-Taktung, Task-Prioritäten, Unterbrechungen (Preemption) und Plattform-Migrationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>$LET_{i, x_{start}}$ (Start-Event / Latch Time):</strong> Diskreter, periodischer oder getriggerter Zeitstempel, der den logischen Beginn des Intervalls markiert.</li>\n<li><strong>$LET_{i, x_{end}}$ (End-Event / Publication Time):</strong> Diskreter Zeitstempel, der das logische Ende des Intervalls markiert und die Ausgabewerte freigibt.</li>\n<li><strong>Logical Execution Time interval:</strong> Zeitintervall $[LET_{i, x_{start}}, LET_{i, x_{end}}]$, das der Ausführungseinheit fest zugeordnet ist.</li>\n<li><strong>EE (Executable Entity):</strong> Die funktionale Ausführungseinheit (im Classic-Kontext typischerweise eine <code>RunnableEntity</code> innerhalb eines OS-Tasks; im Adaptive-Kontext ein Thread/Prozess).</li>\n<li><strong>Communication (Gelbe Blöcke):</strong></li>\n<li><em>Input-Kommunikation ($LET_{i, x_{start}}$):</em> Logisch instantanes Abtasten und Zwischenspeichern (Latch/Shadow Buffer) aller Eingangsdaten über Ports (<code>Sender-Receiver</code>, <code>DataReadAccess</code>).</li>\n<li><em>Output-Kommunikation ($LET_{i, x_{end}}$):</em> Logisch instantanes Bereitstellen und Propagieren aller berechneten Ausgangsdaten (<code>DataWriteAccess</code>) an nachgelagerte Empfänger.</li>\n<li><strong>Execution (Blauer Block EE):</strong> Tatsächliche physische Berechnung auf der CPU (inklusive möglicher Wartezeiten, Kontextwechsel und Unterbrechungen durch höherpriore Tasks/ISRs). Die horizontalen Begrenzungspfeile kennzeichnen die zulässige zeitliche Schwankungsbreite der physischen Ausführung innerhalb des definierten LET-Fensters.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>$t = LET_{i, x_{start}}$ (Logischer Eingang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerung des LET-Intervalls.</li>\n<li>Alle für die EE konfigurierten Eingangsdaten werden atomar aus dem Kommunikationsstack (z. B. COM/RTE) in dedizierte Puffer der EE kopiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Physische Ausführung (beliebig innerhalb des Intervalls):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Betriebssystem (AUTOSAR OS / Adaptive POSIX PSE51) plant die Task/EE ein.</li>\n<li>Die physische Rechenzeit muss strikt genügen: $t_{start, physisch} \\ge LET_{i, x_{start}}$ und $t_{end, physisch} \\le LET_{i, x_{end}}$ (Worst-Case Execution Time $\\text{WCET} \\le \\text{LET-Intervall}$).</li>\n<li>Berechnete Ergebnisse verbleiben zwingend in lokalen Arbeitspuffern und sind für das restliche System noch unsichtbar.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = LET_{i, x_{end}}$ (Logischer Ausgang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Logischer Terminierungszeitpunkt.</li>\n<li>Die lokal gepufferten Ausgabedaten werden atomar in die globalen Sende-Puffer bzw. die RTE/das Netzwerk übertragen und für Folge-Entities bereitgestellt.</li>\n<li>Der Zugriff erfolgt deterministisch zu genau $LET_{i, x_{end}}$, selbst wenn die physische Berechnung der EE bereits weit vor diesem Zeitpunkt beendet war.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Codegenerierung:</strong></li>\n<li>Erfordert RTE-Unterstützung für LET-Puffer (automatische Generierung von Latch- und Shadow-Buffern für Port-Schnittstellen).</li>\n<li>Keine Direct-Memory-Writes zwischen Runnable Entities; Datenaustausch erfordert striktes Double-Buffering oder Copy-on-Read/Write.</li>\n<li><strong>Schedulability & WCET-Analyse:</strong></li>\n<li>Eine Verletzung der Deadline liegt bereits vor, wenn die physische Ausführung $LET_{i, x_{end}}$ überschreitet (Deadline Monitoring via OS oder Watchdog / RTE-Supervision).</li>\n<li>Das LET-Intervall entspricht der maximal zulässigen Worst-Case Response Time (WCRT) inklusive Scheduling-Overhead.</li>\n<li><strong>Multicore- & Verteilte Systeme:</strong></li>\n<li>Ermöglicht implizite Datenkonsistenz und deterministische Datenflüsse über Core- und Steuergerätegrenzen hinweg ohne komplexe Mutex-Sperrmechanismen.</li>\n<li>Eliminiert Race Conditions und Read/Write-Jitter in geschlossenen Regelkreisen (z. B. ADAS, Powertrain, Chassis Control).</li>\n</ul>"}, {"id": "FIG-196ea785e2bda87b", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitliches Ablauf- und Semantikdiagramm (Timing/Execution Model) nach dem Paradigma der <em>Logical Execution Time</em> (LET).</li>\n<li><strong>Technischer Zweck:</strong> Definition der zeitinvarianten, deterministischen Ausführungssemantik für Software-Komponenten (SWC) im AUTOSAR-Gesamtsystem (Classic & Adaptive Platform, spezifiziert im AUTOSAR Glossary sowie in <code>AUTOSAR_TPS_TimingExtensions</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Entkopplung des logischen Zeitverhaltens von der physischen Rechenzeit (Execution Time / Scheduling Jitter). Das Modell garantiert deterministisches Kommunikations- und Echtzeitverhalten unabhängig von Core-Taktung, Task-Prioritäten, Unterbrechungen (Preemption) und Plattform-Migrationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>$LET_{i, x_{start}}$ (Start-Event / Latch Time):</strong> Diskreter, periodischer oder getriggerter Zeitstempel, der den logischen Beginn des Intervalls markiert.</li>\n<li><strong>$LET_{i, x_{end}}$ (End-Event / Publication Time):</strong> Diskreter Zeitstempel, der das logische Ende des Intervalls markiert und die Ausgabewerte freigibt.</li>\n<li><strong>Logical Execution Time interval:</strong> Zeitintervall $[LET_{i, x_{start}}, LET_{i, x_{end}}]$, das der Ausführungseinheit fest zugeordnet ist.</li>\n<li><strong>EE (Executable Entity):</strong> Die funktionale Ausführungseinheit (im Classic-Kontext typischerweise eine <code>RunnableEntity</code> innerhalb eines OS-Tasks; im Adaptive-Kontext ein Thread/Prozess).</li>\n<li><strong>Communication (Gelbe Blöcke):</strong></li>\n<li><em>Input-Kommunikation ($LET_{i, x_{start}}$):</em> Logisch instantanes Abtasten und Zwischenspeichern (Latch/Shadow Buffer) aller Eingangsdaten über Ports (<code>Sender-Receiver</code>, <code>DataReadAccess</code>).</li>\n<li><em>Output-Kommunikation ($LET_{i, x_{end}}$):</em> Logisch instantanes Bereitstellen und Propagieren aller berechneten Ausgangsdaten (<code>DataWriteAccess</code>) an nachgelagerte Empfänger.</li>\n<li><strong>Execution (Blauer Block EE):</strong> Tatsächliche physische Berechnung auf der CPU (inklusive möglicher Wartezeiten, Kontextwechsel und Unterbrechungen durch höherpriore Tasks/ISRs). Die horizontalen Begrenzungspfeile kennzeichnen die zulässige zeitliche Schwankungsbreite der physischen Ausführung innerhalb des definierten LET-Fensters.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>$t = LET_{i, x_{start}}$ (Logischer Eingang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerung des LET-Intervalls.</li>\n<li>Alle für die EE konfigurierten Eingangsdaten werden atomar aus dem Kommunikationsstack (z. B. COM/RTE) in dedizierte Puffer der EE kopiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Physische Ausführung (beliebig innerhalb des Intervalls):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Betriebssystem (AUTOSAR OS / Adaptive POSIX PSE51) plant die Task/EE ein.</li>\n<li>Die physische Rechenzeit muss strikt genügen: $t_{start, physisch} \\ge LET_{i, x_{start}}$ und $t_{end, physisch} \\le LET_{i, x_{end}}$ (Worst-Case Execution Time $\\text{WCET} \\le \\text{LET-Intervall}$).</li>\n<li>Berechnete Ergebnisse verbleiben zwingend in lokalen Arbeitspuffern und sind für das restliche System noch unsichtbar.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = LET_{i, x_{end}}$ (Logischer Ausgang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Logischer Terminierungszeitpunkt.</li>\n<li>Die lokal gepufferten Ausgabedaten werden atomar in die globalen Sende-Puffer bzw. die RTE/das Netzwerk übertragen und für Folge-Entities bereitgestellt.</li>\n<li>Der Zugriff erfolgt deterministisch zu genau $LET_{i, x_{end}}$, selbst wenn die physische Berechnung der EE bereits weit vor diesem Zeitpunkt beendet war.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Codegenerierung:</strong></li>\n<li>Erfordert RTE-Unterstützung für LET-Puffer (automatische Generierung von Latch- und Shadow-Buffern für Port-Schnittstellen).</li>\n<li>Keine Direct-Memory-Writes zwischen Runnable Entities; Datenaustausch erfordert striktes Double-Buffering oder Copy-on-Read/Write.</li>\n<li><strong>Schedulability & WCET-Analyse:</strong></li>\n<li>Eine Verletzung der Deadline liegt bereits vor, wenn die physische Ausführung $LET_{i, x_{end}}$ überschreitet (Deadline Monitoring via OS oder Watchdog / RTE-Supervision).</li>\n<li>Das LET-Intervall entspricht der maximal zulässigen Worst-Case Response Time (WCRT) inklusive Scheduling-Overhead.</li>\n<li><strong>Multicore- & Verteilte Systeme:</strong></li>\n<li>Ermöglicht implizite Datenkonsistenz und deterministische Datenflüsse über Core- und Steuergerätegrenzen hinweg ohne komplexe Mutex-Sperrmechanismen.</li>\n<li>Eliminiert Race Conditions und Read/Write-Jitter in geschlossenen Regelkreisen (z. B. ADAS, Powertrain, Chassis Control).</li>\n</ul>"}], "trans": [{"from": "FIG-bd392762dbe667e8", "to": "FIG-196ea785e2bda87b", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-196ea785e2bda87b", "to": "FIG-bd392762dbe667e8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
